fn frame(t: i32) {
    let w: i32 = host::display::width();
    host::display::clear(0x101018);
    host::display::draw_string(8, 8, "PARENT SHELL", 0xffffff, 2);
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, host::compose::spawn_module("clock", 40, 60, 256, 192));
    }
    let h: i32 = host::display::state_get(1);
    let st: i32 = host::compose::status(h);
    host::display::fill_rect(36, 56, 264, 2, 0x404040);
    host::display::fill_rect(36, 254, 264, 2, 0x404040);
    host::display::fill_rect(36, 56, 2, 200, 0x404040);
    host::display::fill_rect(298, 56, 2, 200, 0x404040);
    if st == 0 {
        host::display::draw_string(48, 130, "LOADING...", 0xffff00, 1);
    }
    if st == 2 {
        host::display::draw_string(48, 130, "EMBED FAILED", 0xff0000, 1);
    }
    if host::display::pointer_down() == 1 {
        let px: i32 = host::display::pointer_x();
        let py: i32 = host::display::pointer_y();
        if px >= 40 && px < 296 && py >= 60 && py < 252 {
            host::compose::focus_module(h);
        } else {
            host::compose::focus_module(-1);
        }
    }
    host::display::draw_number(w - 30, 8, host::compose::module_count(), 0x808080, 1);
    host::display::present();
}
